  OR ((expected->>'public')::boolean AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a WHERE a.grantee=0 AND a.grantor=owner_id AND a.privilege_type='EXECUTE' AND NOT a.is_grantable))
  OR EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a
